    function updateTip(real_wd){
        if(window.__disable_is2 && $.trim(real_wd) == $.trim(kw.val())){
            return;
        }
        if(__hideTip || !bds.comm.supportis){
            if(kw_tip){
                kw_tip.html("");
            }
            return;
        }
        if(pageState==0){
            return;
        }
        if(window.__disable_kw_tip){
            return;
        }
        if(!kw_tip){
            kw_tip=$('<div id="kw_tip" style="width:initial" unselectable="on" onselectstart="return false;" class="s_ipt_tip"/>').insertBefore(kw);
            kw_tip.parent().click(
                function(e){
                    var obj=kw.get(0);
                    if(e.target===obj){
                        return true;
                    }
                    obj.focus();
                    var len = obj.value.length;
                    if (document.selection) {
                        var sel = obj.createTextRange();
                        sel.moveStart('character', len);
                        sel.collapse();
                        sel.select();
                    } else if (typeof obj.selectionStart == 'number'
                        && typeof obj.selectionEnd == 'number') {
                        obj.selectionStart = obj.selectionEnd = len;
                    }
                    return false;
                }
            );
            kw_tip.get(0).onselectstart = function() {
                return false;
            };
        }
        kw_tip.text(real_wd);
        if(real_wd!=""){
            //要重新设一下value是为了支持诡异的ie8、9
            var textWidth=kw.textWidth();
            //14 is 2 x padding-left
            kw_tip.css({"opacity":0,"margin-left":textWidth+20+"px","max-width":kw_tip.parent().width()-textWidth-14+"px"}).text(real_wd);
            if(window.__disable_is2){
                kw_tip.css("z-index",1);
            }
            kw_tip.show();
        }else{
            kw_tip.hide();
        }
    }


