    function form_submit(ev){
        // 记录异步的开始时间点，输入框spy交互时间统计需要
        bds.comm.asyncStartTiming = performance && performance.now 
            ? performance.now()
            : null;
        if(!URL.support()){
            return true;
        }
        if(disableSubmit){
            return false;
        }
        disableSubmit=true;
        kw.blur();
        updateTip("");
        if($(this).attr("target")){
            return true;
        }
        afterUserSubmit=true;
        afterUserSubmitTimeout=setTimeout(function(){
            afterUserSubmit=false;
        },1000);
        try{
            var showDefaultQuery = $('#kw').attr('placeholder') || $('.kw-placeholder').text();
            // 有默置 query 时 submit 不跳首页，而是发起搜索
            if (!$.trim(kw.val())) {
                // 有默置 query 不跳"/"
                if (!showDefaultQuery) {
                    location.href = "/";
                    return false;
                }
            }
            var newEnv=new PageEnv();
            var form_data=$(this).serializeArray(),i;
            for(i=0;i<form_data.length;i++){
                newEnv.p(form_data[i].name,form_data[i].value);
            }

            if (showDefaultQuery && !$.trim(kw.val())){
                // 有默置 query且 input value为空，才使用默置 query 作为 value
                newEnv.p("wd", showDefaultQuery);
                // 有默置 query 添加 rsv_dq=1
                newEnv.p("rsv_dq", 1);
            }
            else if($.trim(kw.val())) {
                newEnv.p("wd",kw.val());
            }

            if(newEnv.p("nojc")){
                newEnv.p("nojc","");
            }
            if(currentCacheItem){
                if(
                        (
                         newEnv.equals(currentCacheItem.env.clone({"wd":currentCacheItem.real_wd}))
//                        ||newEnv.equals(currentCacheItem.env.clone({"wd":currentCacheItem.prw}))
                        )
                        && !currentCacheItem.force
                        ){
                    genSendConfirm(currentCacheItem,oldCacheItem,22)();
                    currentCacheItem.force=true;

                    //键盘操作的，页面已经展现完成，这时候不要再重新刷新
                    updateTip("");
                    updateJc(currentCacheItem);
                    return false;
                }
                //newEnv.p("bs",currentCacheItem.env.p("wd"));
                if(currentCacheItem.env.p("rsv_spt")){
                    newEnv.p("rsv_spt",currentCacheItem.env.p("rsv_spt"));
                }
            }
            //wrapper_wrapper.empty();
            //wrapper_wrapper.html("<div style='margin:30px 0 0 162px;font-size:13px;color:#666'>请按“回车”键发起检索</div>");

            //原生submit有ev参数就强刷，js的submit尝试用cache
            URL.submit(newEnv,!!ev);
        }catch(e){
            console.error(e);
        }
        return false;
    }

