    function preloadKw(_options){
        var options={
            'force':false,
            'no_predict':false,
            'use_cache':false,
            'shouldShow':true,
            'pstg':-1
        };
        if(_options){
            $.extend(options,_options);
        }
        var env=options.env,
            force=options.force,
            no_predict=options.no_predict,
            shouldShow=options.shouldShow,
            use_cache=options.use_cache,
            cacheItem;
        //debugger;
        if(!env||!env.p("wd")||!env.hashCode()){
            return;
        }

        // 预测请求下区分首页/结果页与语音/文本输入
        if(!no_predict){
            var isHome = bds && bds.comm && bds.comm.ishome;
            var isVoice = bds && bds.comm && bds.comm.isVoice;
            var rsvDl = '';

            if(isVoice){
                rsvDl = isHome ? 'ivoice_pre' : 'bvoice_pre';
            }
            else {
                rsvDl = isHome ? 'ib_pre' : 'tb_pre';
            }

            env.p('rsv_dl', rsvDl);
        }

        if((disablePreload||Cookie.get('ISSW')==1)&&!force&&no_predict){
            return;
        }
        if((disablePredict||Cookie.get('ISSW')==1)&&!force&&!no_predict){
            return;
        }

        if(
            use_cache  &&
            (cacheItem=html_cache.hasCache(env,{loaded:true}))
            ){
            if(shouldShow){
                if(!currentCacheItem||
                        !cacheItem.env.clone({"wd":cacheItem.real_wd}).equals(currentCacheItem.env.clone({"wd":currentCacheItem.real_wd}))
                        ){
                    cacheItem.force=options.force;
                    cacheItem.no_predict=options.no_predict;
                    //cacheItem.prw.push[me.value];

                    //使用缓存，pdc只做清理工作
                    cacheItem.pdc.init();
                    //只有cacheItem.force为true时，才是用户确认
                    if(cacheItem.force) {
                        cacheItem.pdc.mark('st');
                        if(window.bds && bds.comm && !bds.comm.supportis){
                            cacheItem.pdc.mark('net');
                            cacheItem.pdc.setParam('cus_hitpreload',1);
                        }
                    }
                    mergePreloadLog(cacheItem, {
                        frcache: 1
                    });
                    swap_wd(env,cacheItem);
                }
                updateTip((options.no_predict&&options.pstg!=6)?"":cacheItem.real_wd);
                updateJc(cacheItem);
            }
            return;
        }
        if(force&&shouldShow&&no_predict){
            // 当页面刷新时，需隐藏 toast
            $('.search-keyboard-toast').hide();
            addMask();
        }

        cacheItem={'env':env,'cftime':0,'no_predict':no_predict,shouldShow:shouldShow,'loaded':false,'force':force,'startTime':new Date().getTime(),log:{'ctime':new Date().getTime()-pageStartTime,
            'wd':env.p("wd"),
            'ntime':0,
            'stat':0,
            'used':0,
            'rtime':0,
            'utime':(force?new Date().getTime()-pageStartTime:0),
            'res':0}};
        cacheItem.pdc = pdc(cacheItem);
        if(options.pstg>0){
            cacheItem.pstg = options.pstg;
        }
        if(cacheItem.force) {
            cacheItem.pdc.mark('st');
        }
        cacheItem.base64 = isbase64(cacheItem.pdc);
        preloadLogs.push(cacheItem.log);
        preload_num++;
        preload_cnt++;

        // 输入框触发的load需要做一下过滤
        load(cacheItem, true);
    }
