    var stopPreloadTimeout,stopPredictTimeout;
    function stopPreload(time,is_predict){
        //预测请求和非预测请求的开关要分开，所以多传is_predict参数
        if(!is_predict){
            disablePreload=true;
            if(stopPreloadTimeout){
                clearTimeout(stopPreloadTimeout);
                stopPreloadTimeout=false;
            }
            stopPreloadTimeout=setTimeout(function(){
                disablePreload=defaultDisablePreload;
            },time);
        }else{
            disablePredict=true;
            if(stopPredictTimeout){
                clearTimeout(stopPredictTimeout);
                stopPredictTimeout=false;
            }
            stopPredictTimeout=setTimeout(function(){
                disablePredict=defaultDisablePredict;
            },time);
        }
    }
