$(function () {
    var surveyOptions = bds && bds.comm && bds.comm.smartSearchBox && bds.comm.smartSearchBox.userResearch;
    // 后端控制展现的优先级最高
    if (!surveyOptions || surveyOptions.isShow !== '1') {
        return;
    }

    var SURVEY_CLICKED_BASE_LS = 'surveyLinkClicked_';
    var SURVEY_TOAST_BASE_LS = 'surveyLinkToasted_';
    var curClickedLs = SURVEY_CLICKED_BASE_LS + (surveyOptions.version || '');
    var curToastedLs = SURVEY_TOAST_BASE_LS + (surveyOptions.version || '');

    // 前端记录是否点击过，点击过不再展现
    try {
        if (localStorage.getItem(curClickedLs)) {
            return;
        }
    } catch (e) {}
    require(['modules/page-log/ubc-log'], function (Ubc) {
        Ubc.sendUbcLog(18463, 'show', 'survey_area');
    });
    var isHome = bds && bds.comm && bds.comm.ishome;

    // 初始化 link
    var $surveyLinkDom = $('<a>', {
        href: surveyOptions.url,
        target: '_blank',
        text: surveyOptions.entryText,
        'class': 'survey' + (isHome ? ' s-top-right-new c-font-normal s-top-right-text' : '')
    });

    // link事件绑定
    eventBind();

    // 挂载到用户区
    var $container = isHome ? $('#u1') : $('#u');
    if ($container.length) {
        if ($container[0].firstChild) {
            $surveyLinkDom.prependTo($container);
        } else {
            $container.append($surveyLinkDom);
        }
    }

    // 结果页添加窄屏兼容样式
    if (!isHome) {
        $('.wrapper_new #head').addClass('survey-head');
    }

    // 初始化 toast
    var isShowToast = false;
    try {
        var curCount = localStorage.getItem(curToastedLs);
        if (curCount === '1') {
            isShowToast = true;
        }
    } catch (e) {}

    var toastTimer = null;
    var $surveyToastDom = $('<div>', {
        'class': 'survey-tooltip'
    }).html(
        '<div class="survey-tooltip-content">' +
            (isShowToast ? surveyOptions.toast : surveyOptions.hoverText) +
        '</div>' +
        '<div class="survey-tooltip-arrow"></div>'
    );

    $surveyLinkDom.append($surveyToastDom);
    hideToast();
    if (isShowToast) {
        try {
            localStorage.setItem(curToastedLs, '2');
        } catch (e) {}
        setTimeout(() => {
            showToast();
            toastTimer = setTimeout(function () {
                hideToast();
            }, 3000);
        }, 5000);
    } else {
        try {
            localStorage.setItem(curToastedLs, '1');
        } catch (e) {}
    }

    // 弹窗展现
    function showToast() {
        $surveyToastDom.css('visibility', 'visible');
    }

    // 弹窗隐藏
    function hideToast() {
        $surveyToastDom.css('visibility', 'hidden');
    }

    // 变更弹窗文案
    function changeToastText() {
        if (!surveyOptions.hoverText) {
            return;
        }
        $surveyToastDom.find('.survey-tooltip-content').text(surveyOptions.hoverText);
    }

    // 事件绑定
    function eventBind() {
        $surveyLinkDom.on('mouseenter', function () {
            if (toastTimer) {
                clearTimeout(toastTimer);
                toastTimer = null;
                changeToastText();
            }
            showToast();
        });

        $surveyLinkDom.on('mouseleave', function () {
            hideToast();
        });

        $surveyLinkDom.on('click', function () {
            require(['modules/page-log/ubc-log'], function (Ubc) {
                Ubc.sendUbcLog(18463, 'click', 'survey_area');
            });
            try {
                localStorage.setItem(curClickedLs, '1');
            } catch (e) {}
            $surveyLinkDom.hide();
        });
    }
});
