// 前端展现日志
$(window).on('swap_begin', function () {
    if (bds && bds.se && bds.se.displayTime !== undefined && bds.se.displayTime !== null) {
        clearTimeout(bds.se.displayTime);
        bds.se.displayTime = null;
    }
}).on("confirm",function(){
    if (bds && bds.comm && bds.comm.globalLogFlag && bds.comm.globalLogFlag == 1) {
        if (bds.comm.logFlagNoNetwork == 1 || bds.comm.logFlagNoIntegration == 1) { // 无展现日志逻辑
        } else {
            bds.se.displayTime = setTimeout(function(){
                bds && bds.se && bds.se.display();
                bds.se.displayTime = null;
            }, 5000);
        }
    }
    if (bds){
        bds.se.userAction.collect();
    }
}).on("swap_end",function(e,cacheItem){
    if(!cacheItem && bds && bds.comm && bds.comm.globalLogFlag && bds.comm.globalLogFlag == 1){
        if (bds.comm.logFlagNoNetwork == 1 || bds.comm.logFlagNoIntegration == 1) { // 无展现日志逻辑
        } else {
            bds.se.displayTime = setTimeout(function(){
                bds && bds.se && bds.se.display();
                bds.se.displayTime = null;
            }, 5000);
        }
    }
    if(!cacheItem && bds){
        bds.se.userAction.collect();
    }

    // 给op (mashuchao) 发送webb监控日志 by huanghuiquan
    // 在每次搜索展现结果后发送监控日志
    bds.log.send.sendNow('flow_monitor', {}, {qid: bds.comm.qid, log: {}, len: 1})
});

    $(window).on("swap_end",function(){
        if(bds.comm.__rdNum && bds.comm.__rdNum > 9000){
            setTimeout(function(){
                $.ajax({
                    "dataType":"script",
                    "cache":true,
                    "url":"http://pss.bdstatic.com/r/www/cache/static/plugins/clean_6ff7eac.js",
                    "success":function(){
                        bds.se.cleanCookie.init();
                    }
                });
            },0);
        }
    });

    window.icodetest = 12;

//浏览器缩放比不正常提示
$(window).on('swap_end',function () {
    if (bds && bds.comm && bds.comm.sampleval && $.inArray('ZOOM_TEST', bds.comm.sampleval) > -1) {
        require(['plugins/zoom_prompt'], function (resetZoom) {
            resetZoom()
        })
    } else if (bds && bds.comm && bds.comm.sampleval && $.inArray('ZOOM_COMP', bds.comm.sampleval) > -1) {
        require(['lib/get_zoom'], function (getZoom) {
            var zoom = getZoom();
            if (!!zoom && zoom != 1) {
                ns_c({
                    'fm': 'behs',
                    'qid': bds.comm.qid,
                    'tab': 'baidu_zoomshow'
                });
            }
        })
    }
});

// 彩蛋换肤
$(window).on('swap_end', function () {
    var bonus_scene_head = $("#bonus_scene_head");
    bonus_scene_head.remove();
});

// pc跨屏扫码至wise实验
$(window).on('swap_end', function() {
    if (bds && bds.comm && bds.comm.sampleval && $.inArray('qrcode', bds.comm.sampleval) > -1) {
        var encodedQuery = encodeURIComponent(bds.comm.query);
        if (encodedQuery.length <= 150) {
            require(['plugins/pcToWise'], function(pcToWise) {
                pcToWise(encodedQuery);
            });
        }
    }
});

$(document).ready(function () {
    require(['plugins/safeIcon'], function (safeIcon) {
        safeIcon.init();
    })
});


$(document).ready(function () {
    if (bds.comm && bds.comm.ishome && !$('.s_tab .s_tab_inner').get(0)) {
        $( ".s_tab" ).wrapInner("<div class='s_tab_inner'></div>");
    }
});

$(window).on('swap_end', function (e, cacheItem) {
    require(['plugins/title_highlight'], function (highlight) {
        highlight.init();
    });
    // 适配ipad的浏览器
    require(['plugins/compatible_ipad_input'], function (init) {
        init();
    });
});

(function () {
    require(['modules/page'], function (Module) {
        var pageModule = new Module.PageModule();
        var resultDI = pageModule.resultDI;
        var resultModule;

        $(window).on('swap_dom_ready', function () {
            pageModule.updated();
        }).on('swap_end', function (e, cacheItem) {
            if ($('#content_left').length > 0) {
                var offsetLeft = $('#content_left').offset().left;
                $('#content_left').css({
                    'margin-left': -offsetLeft + 'px',
                    'padding-left': offsetLeft + 'px'
                });
            }
            if ($('[tpl="app/rs"]').length > 0) {
                var offsetLeftRs = $('[tpl="app/rs"]').offset().left;
                $('[tpl="app/rs"]').css({
                    'margin-left': -offsetLeftRs + 'px',
                    'padding-left': offsetLeftRs + 'px'
                });
            }
            require(['modules/result'], function (Module) {
                resultModule = new Module.ResultModule(resultDI, cacheItem);
            });
        }).on('swap_begin', function () {
            resultModule && resultModule.destroy();
        }).on('confirm', function () {
            resultModule && resultModule.asyncConfirm();
        });

        // if (!bds.comm.ishome) {
            $(document).ready(function () {
                pageModule && pageModule.domReady();
            });
            $(window).load(function() {
                pageModule && pageModule.onload();
            });
        // }
    });

    require(['modules/extra-plugin-monitor/dom-monitor', 'modules/extra-plugin-monitor/block-monitor']);
})();


$(window).on('swap_end', function (e, cacheItem) {
    var $html = $('html');
    var $body = $('body');
    // 无结果页容器
    var $nocontent = $('.content_none');
    // 当前是否无结果页
    var isNoContent = ($nocontent && $nocontent.length > 0) || false;
    // html DOM上是否已有置灰类名
    var domHasGray = $html.hasClass('big-event-gray');
    // conent中置灰字段的值
    var isGray = bds && bds.comm && bds.comm.isGray;

    // 清除首页body上的置灰类名
    $body.hasClass('big-event-gray') && $body.removeClass('big-event-gray');

    // 如果html已有置灰类名，且不为无结果页, 当前不需要置
    if(domHasGray && !isNoContent && !isGray) {
        $html.removeClass('big-event-gray');
    }
    // 如果html无置灰类名，且当前需要置灰
    if(!domHasGray && isGray) {
        $html.addClass('big-event-gray');
    }
});


$(window).on('swap_end', function () {
    // 记录发起新搜索的时间
    try {
        localStorage.setItem('search_request_time', Date.now());
    } catch (err) {
        console.error(err);
    }
});


// ai_office 卡片退化
$(window).on('swap_end', function () {
    var bannerCard = document.querySelector('#content_left [tpl=ai_office]');
    var rightContentElement = document.getElementById('content_right');
    if (!bannerCard) {
        return;
    }
    var bannerCardTop = bannerCard.getBoundingClientRect().top
        - document.getElementById('container').getBoundingClientRect().top;

    // 通栏卡退化到左侧队列，遮挡右边栏，修改margin高度
    var rightContentMarginTop = bannerCardTop + bannerCard.offsetHeight;
    rightContentElement.style.marginTop = rightContentMarginTop + 27 + 'px';
    rightContentElement.style.visibility = 'visible';
});

